"""Generated score: a slow synth pad under the film, written as a WAV."""
import numpy as np

SR = 48000
DUR = 30.0


def note(f, t, harmonics=(1.0, 0.42, 0.20, 0.09), detune=0.0012):
    """Warm additive tone, lightly chorused."""
    out = np.zeros_like(t)
    for k, amp in enumerate(harmonics, start=1):
        for d in (-detune, detune):
            out += amp * np.sin(2 * np.pi * f * k * (1 + d) * t
                                + k * 1.3 + d * 1000)
    return out / (len(harmonics) * 2)


def env(t, t0, t1, attack=1.4, release=2.2):
    a = np.clip((t - t0) / attack, 0, 1)
    r = np.clip((t1 - t) / release, 0, 1)
    a = a * a * (3 - 2 * a)
    r = r * r * (3 - 2 * r)
    return a * r


